class Solution {
    public int[] leftRightDifference(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int leftSum = 0;
            for (int left = 0; left < i; left++) {
                leftSum += nums[left];
            }
            int rightSum = 0;
            for (int right = i + 1; right < n; right++) {
                rightSum += nums[right];
            }
            ans[i] = Math.abs(leftSum - rightSum);
        }
        return ans;
    }
}

class Solution {
    public int[] leftRightDifference(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        for (int i = 1; i < n; i++) {
            left[i] = left[i - 1] + nums[i - 1];
        }
        for (int i = n - 2; i >= 0; i--) {
            right[i] = right[i + 1] + nums[i + 1];
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = Math.abs(left[i] - right[i]);
        }
        return ans;
    }
}

class Solution {
    public int[] leftRightDifference(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        int[] ans = new int[nums.length];
        int leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            int rightSum = total - leftSum - nums[i];
            ans[i] = Math.abs(leftSum - rightSum);
            leftSum += nums[i];
        }
        return ans;
    }
}

class Solution {
    public int[] leftRightDifference(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        int rightSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            ans[i] = rightSum;
            rightSum += nums[i];
        }

        int leftSum = 0;
        for (int i = 0; i < n; i++) {
            int current = nums[i];
            ans[i] = Math.abs(leftSum - ans[i]);
            leftSum += current;
        }
        return ans;
    }
}
